mapper.update:
UPDATE t_order_payment_projection SET intent_status='SUCCEEDED',active_attempt_id=NULL,
    last_attempt_id=#{attemptId},last_attempt_status='SUCCEEDED',successful_attempt_id=#{attemptId},
    captured_amount=#{capturedAmount},attempt_source_version=#{sourceVersion},
    last_intent_event_key=#{eventKey},last_intent_payload_hash=#{payloadHash},
    last_attempt_event_key=#{eventKey},last_attempt_payload_hash=#{payloadHash},
    last_event_time=#{eventTime},version=version+1,update_time=#{now}
WHERE order_payment_projection_id=#{payment.orderPaymentProjectionId} AND order_id=#{payment.orderId}
    AND payment_intent_id=#{payment.paymentIntentId} AND version=#{payment.version}
    AND successful_attempt_id IS NULL AND intent_status <> 'SUCCEEDED'
